import{_ as e,c as i,o as t,a2 as l}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"安装","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/installation.md","filePath":"zh-CN/guide/installation.md","lastUpdated":1793163976000}'),o={name:"zh-CN/guide/installation.md"};function s(r,a,n,p,h,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><p>NueZip 可通过 Mac App Store 在 macOS 上使用。</p><h2 id="下载方式" tabindex="-1">下载方式 <a class="header-anchor" href="#下载方式" aria-label="Permalink to &quot;下载方式&quot;">​</a></h2><h3 id="mac-app-store-推荐" tabindex="-1">Mac App Store（推荐） <a class="header-anchor" href="#mac-app-store-推荐" aria-label="Permalink to &quot;Mac App Store（推荐）&quot;">​</a></h3><ul><li><strong>下载</strong>：<a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">Mac App Store 上的 NueZip</a></li></ul><p>Mac App Store 版本提供自动更新，并与 macOS 无缝集成。</p><h3 id="github-releases-备选" tabindex="-1">GitHub Releases（备选） <a class="header-anchor" href="#github-releases-备选" aria-label="Permalink to &quot;GitHub Releases（备选）&quot;">​</a></h3><p>如果你更希望直接下载，可以从 <a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 获取该应用。请注意，此版本不会获得自动更新。</p><h2 id="安装步骤" tabindex="-1">安装步骤 <a class="header-anchor" href="#安装步骤" aria-label="Permalink to &quot;安装步骤&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>点击上方的下载链接，或在 Mac App Store 中搜索 &quot;NueZip&quot;</li><li>点击 &quot;Get&quot; 下载该应用</li><li>应用将自动下载并安装</li><li>从你的应用程序文件夹或 Launchpad 启动 NueZip</li></ol><h3 id="github-releases" tabindex="-1">GitHub Releases <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;GitHub Releases&quot;">​</a></h3><ol><li>从 Releases 页面下载最新的 <code>.dmg</code> 文件</li><li>双击下载的 <code>.dmg</code> 将其打开</li><li>将 <code>NueZip.app</code> 图标拖入你的 <code>Applications</code> 文件夹</li><li>退出已挂载的镜像，并从 <code>Applications</code> 打开 <code>NueZip</code></li></ol><p>如果 macOS 阻止打开应用（Gatekeeper），请打开 <strong>系统设置 → 隐私与安全性</strong>，为 NueZip 点击 <strong>仍要打开</strong>，或右键点击应用并选择 <strong>打开</strong>。</p><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to &quot;首次启动&quot;">​</a></h2><p>当你首次启动 NueZip 时，会引导你完成一个新手引导流程：</p><ul><li><strong>授予文件夹访问权限</strong>：允许 NueZip 访问常用目录（下载、文稿、桌面）</li><li><strong>启用 Finder 扩展</strong>：激活右键上下文菜单，以便快速进行归档操作</li></ul><p>在弹出提示时授予权限。你可以随时在 <strong>系统设置 → 隐私与安全性</strong> 中修改这些设置。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><ul><li><strong>Mac App Store 版本</strong>：更新由 App Store 自动处理</li><li><strong>GitHub Releases 版本</strong>：下载较新的版本并替换 <code>Applications</code> 中的旧应用</li></ul><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><p>要卸载 NueZip：</p><ol><li>退出 NueZip</li><li>将 <code>NueZip.app</code> 从 <code>Applications</code> 拖入废纸篓</li><li>（可选）移除应用数据与日志：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Logs/nuezip</span></span></code></pre></div><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><ul><li><strong>macOS</strong>：推荐 Sonoma（14）或更高版本</li><li><strong>CPU</strong>：Apple Silicon（M 系列）或 Intel（64 位）</li><li><strong>内存</strong>：最低 4GB，推荐 8GB</li><li><strong>存储空间</strong>：约 50 MB</li></ul><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><p>如果在安装过程中遇到问题：</p><ul><li><strong>macOS 阻止打开应用</strong>：打开 <strong>系统设置 → 隐私与安全性</strong>，为 NueZip 点击 <strong>仍要打开</strong></li><li><strong>公证警告</strong>：从 Mac App Store 下载经过签名/公证的构建版本</li></ul><p>如需更多帮助，请访问 <a href="./troubleshooting.html">故障排除指南</a>。</p>`,30)])])}const g=e(o,[["render",s]]);export{u as __pageData,g as default};
